#version 450
layout(location = 0) in vec2 uv;
layout(location = 0) out vec4 color;
layout(set = 0, binding = 0) uniform sampler2D source;
layout(set = 0, binding = 1) uniform Params { float time; float amplitude; float wavelength; } params;

void main() {
    vec2 size = vec2(textureSize(source, 0));
    // amplitude and wavelength in pixels; one wave travels down per second.
    float phase = (uv.y * size.y / params.wavelength - params.time) * 6.2831853;
    float offset = sin(phase) * params.amplitude / size.x;
    color = texture(source, uv + vec2(offset, 0.0));
}
